# Each embedded image is a WebP crop or composite from the supplied reference frames.



def image(asset, x, y, width, height):
    return (f'<image href="{ASSETS[asset]}" x="{x}" y="{y}" width="{width}" '
            f'height="{height}" preserveAspectRatio="none"/>')


def rect(x, y, w, h, fill, radius=0, stroke="none", sw=1, extra=""):
    return (f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{radius}" '
            f'fill="{fill}" stroke="{stroke}" stroke-width="{sw}" {extra}/>')


def label(x, y, value, size=14, color="#fff", weight=750, anchor="middle", extra=""):
    return (f'<text x="{x}" y="{y}" font-family="Dice Rubik,DejaVu Sans,Arial,sans-serif" font-size="{size}" '
            f'font-weight="{weight}" fill="{color}" text-anchor="{anchor}" {extra}>{escape(value)}</text>')


def button(key, title, drawing):
    return (f'<g class="action" tabindex="0" role="button" data-action="{key}" '
            f'aria-label="{escape(title, quote=True)}"><title>{escape(title)}</title>{drawing}</g>')


def die(x, y, color="#ffa400"):
    return (rect(x, y, 66, 66, color, 10, "#fff", 5)
            + f'<circle cx="{x+33}" cy="{y+33}" r="6" fill="#fff"/>')


def stamp(key, x, y, width, height, extra=""):
    return ASSETS[key].replace("<svg ", f'<svg x="{x}" y="{y}" width="{width}" height="{height}" {extra} ', 1)


def rail(side):
    left = side == "l"
    x0 = 216 if left else 1340
    rows = 8 if left else 9
    height = 905 if left else 989
    pieces = [f'<g transform="translate({x0*1111/1920} {(325-80.5)*1111/1920}) scale({1111/1920})">',
              rect(7,7,348,height,"#111114",19,"white",4,'fill-opacity=".84"'),
              stamp("topArt",41,32,281,28)]
    for i in range(rows):
        prefix = side + str(i)
        delta = round(i * 98.3)
        x = 6 if not left and i == 0 else 0
        multi = left and i == 7
        h = 102 if multi else 85
        y = 96 + delta
        cy = 139 + delta + (8 if multi else 0)
        yname = cy - (38 if multi else 23)
        ytag = cy + (15 if multi else 5)
        pieces.extend([rect(31+x,y,301,h,"#848287",12),
                       rect(37+x,y+1,289,h-2,"#131317",9),
                       image(prefix,x+53,cy-29,58,58).replace('<image ',f'<image clip-path="url(#{prefix}clip)" '),
                       f'<defs><clipPath id="{prefix}clip"><circle cx="{x+82}" cy="{cy}" r="28.5"/></clipPath></defs>',
                       stamp(prefix+"name",x+124,yname,186,ytag-yname),
                       stamp(prefix+"tag",x+124,ytag,183,23)])
        if prefix+"seal" in ASSETS:
            dx,dy=ASSETS[prefix+"seal"]
            pieces.append(f'<use href="#seal" transform="translate({x+124+dx} {yname+dy})"/>')
    return ''.join(pieces)+'</g>'


DEFS = """<defs>
<linearGradient id="gold" x2="0" y2="1" gradientUnits="objectBoundingBox"><stop stop-color="#fff36a"/><stop offset=".29" stop-color="#ffcf28"/><stop offset="1" stop-color="#f59b08"/></linearGradient>
<g id="seal"><path fill="#ebae00" d="M0-11 4-10 7-8 10-6 10-2 12 1 10 5 7 7 5 10 1 10-3 12-6 9-9 8-10 4-11 1-10-3-9-7-5-8-3-11Z"/><path fill="none" stroke="#624500" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" d="m-4 0 3 3 5-7"/></g></defs>"""


def selector(x, key, title, value):
    if key == 'count':
        ink = stamp('fourArt',x+10,232,13,16)+stamp('diceArt',x+26,232,40,16)
    elif key == 'mode':
        ink = stamp('colorArt',x+10,232,54,16)+stamp('diceArt',x+66,232,35,16)
    else:
        ink = stamp('blackArt',x+9,232,56,16)
    content = (rect(x,219,121,41,"#fbfbfc",7,"#bababa",2)
               + f'<g id="{key}-ink">{ink}</g>'
               + label(x+10,246,"",14,"#161619",900,"start",f'id="{key}-label" stroke="#161619" stroke-width=".55" letter-spacing=".6"')
               + f'<path d="M{x+102} 238 l4 4 4 -4" fill="none" stroke="#171719" stroke-width="1.8"/>')
    return button(key,title,content).replace('role="button"', 'role="button" aria-haspopup="listbox" aria-expanded="false"')
def artwork_title():
    return stamp("titleArt",396,160,318,34)


def scene():
    art = [DEFS,image("world",0,0,1111,971),image("logo",373,50,363,63),
           '<g id="rails">',rail("l"),rail("r"),'</g>',
           button("blur","Toggle blur",image("blur",814,728,133,39)+label(880,751,"",11,extra='id="blur-label"')),
           rect(344,145,421,1030,"#101012",12,"#ededed",2,'id="board" fill-opacity=".88"'),
           artwork_title(),
           selector(363,"count","Number of dice","4 DICE"),selector(494,"mode","Roll mode","COLOR DICE"),
           selector(626,"theme","Board color","BLACK"),
           f'<g id="dice" aria-label="Orange die">{die(522,286)}</g>', '<g id="below">',label(551,412,"ID: —",11,extra='id="roll-id"'),
           button("verify","Verify last roll",rect(603,390,57,28,"transparent")+label(627,412,"Verify",12,extra='text-decoration="underline"')),
           button("roll","Roll again",rect(362,425,386,41,"#a25700",10)+rect(362,425,386,37,"url(#gold)",9,"#ffdb7c",2)+stamp("rollArt",467,430,175,21,'style="filter:drop-shadow(0 1px 1px #a44e00) drop-shadow(0 -1px 1px #ad5900)"')),
           rect(363,481,385,96,"#151519",8,"#363638",1.5),
           button("items","Choose score item",rect(429,501,81,55,"#0c0c0e",8,"#5a5a5b")+image("item0",447,508,46,40).replace('<image ','<image id="chosen-item" ')),
           label(555,543,"+0",32,extra='id="score"')]
    for direction,x in [(-1,389),(1,725)]:
        for i,amount in enumerate([1,.25,5,10]):
            delta=direction*amount
            art.append(button("score"+str(delta),f"Change score by {delta:+}",rect(x-20,486+i*20,40,20,"transparent")
                              +label(x,501+i*20,f"{delta:+}",10,"#79e293" if direction==1 else "#fa808c")))
    for x,w,txt,ident in [(416,124,"Rolls Today: 0","today"),(551,140,"Users Online: 1","online")]:
        art.extend([rect(x,592,w,30,"#18181b",8,"#343439"),label(x+w/2,611,txt,10,extra=f'id="{ident}"')])
    art.extend([rect(363,636,385,64,"#111d23",9,"#1d444e"),label(374,655,"Global Goal: 250,000 Dice Rolled",10,anchor="start"),
                label(737,655,"0%",10,"#3dd8e6",anchor="end",extra='id="percent"'),
                rect(375,665,360,7,"#27393b",4),rect(375,665,0,7,"#23d6a8",4,extra='id="bar"'),
                label(375,689,"updates every 30 seconds",8,"#c0c5cb",anchor="start"),label(737,689,"Total World Rolls: 0 / 250,000",9,anchor="end",extra='id="total"'),
                '<text x="555" y="730" text-anchor="middle" fill="#ddd" font-family="DejaVu Sans,sans-serif" font-size="12">Possible colors are: '])
    for name,color in COLORS.items():
        art.append(f'<tspan fill="{color}" font-weight="bold">{name}{", " if name != "Purple" else "."}</tspan>')
    art.extend(['</text>',label(555,784,"LAST 25 ROLLS",10),rect(363,796,385,19,"#0e0e10",7,"#303035"),'<g id="history"></g>',
                rect(363,837,385,205,"#17171b",11,"#57575b"),label(555,869,"HOW DOES OFFLINE DICE WORK?",15),
                label(555,897,"Choose between 1 and 100 dice, then press ROLL AGAIN!",11),
                label(555,919,"Each die draws a color independently.",11),
                label(555,954,"Next roll lets you exclude one color for a single throw.",11),
                label(555,976,"Open Verify to see the colors and settings of your last roll.",10),
                '</g>'])
    return ('<svg xmlns="http://www.w3.org/2000/svg" id="scene" viewBox="0 0 1111 1190" '
            'aria-label="Offline Dice game">'+''.join(art)+'</svg>')


